import{_ as a,C as s,o as i,c as r,j as e,a as n,G as d,a3 as c}from"./chunks/framework.B6x8LOwa.js";const k=JSON.parse('{"title":"URL Commands","description":"Control ICC-CE via icc:// protocol URLs, including toolbar, tools, ink, whiteboard, configuration profiles, and more","frontmatter":{"title":"URL Commands","description":"Control ICC-CE via icc:// protocol URLs, including toolbar, tools, ink, whiteboard, configuration profiles, and more"},"headers":[],"relativePath":"en/guide/url-commands.md","filePath":"en/guide/url-commands.md"}'),l={name:"en/guide/url-commands.md"};function h(p,t,u,m,g,b){const o=s("ArticleMetadata");return i(),r("div",null,[t[0]||(t[0]=e("h1",{id:"url-commands",tabindex:"-1"},[n("URL Commands "),e("a",{class:"header-anchor",href:"#url-commands","aria-label":'Permalink to "URL Commands"'},"​")],-1)),d(o),t[1]||(t[1]=c(`<p>ICC-CE supports controlling the software via URLs starting with <code>icc://</code>. You can create desktop shortcuts for common operations, or integrate them with classroom control systems and signage systems.</p><p>Typical use cases:</p><ul><li>Switch to your preferred configuration profile with one command before class</li><li>Clear all ink and collapse the toolbar with one click after class</li><li>Let physical buttons on the control panel switch pens and erasers directly</li></ul><h2 id="enable-the-feature-first" tabindex="-1">Enable the Feature First <a class="header-anchor" href="#enable-the-feature-first" aria-label="Permalink to &quot;Enable the Feature First&quot;">​</a></h2><p>This feature is <strong>disabled by default</strong> — you need to enable it first:</p><ol><li>Open Settings → <strong>Startup</strong></li><li>Find <strong>External Protocol Call (icc://)</strong>, described as &quot;Control the software externally via icc:// protocol&quot;</li><li>Turn the toggle on</li></ol><div class="warning custom-block"><p class="custom-block-title">Commands are ignored when the toggle is off</p><p>The software won&#39;t show any prompt — the command simply does nothing. If you&#39;ve been trying without success, first check that this toggle is enabled.</p></div><div class="warning custom-block"><p class="custom-block-title">If you moved the software folder, turn the toggle off and on again</p><p>ICC-CE is a portable application. If you move, rename, or change the drive of the entire folder, the commands will stop working — but <strong>the toggle will still show as enabled</strong>, with no visible indication of the issue.</p><p>The reason is that the recorded startup location still points to the old path. The fix is simple: turn the <strong>External Protocol Call</strong> toggle <strong>off, then back on again</strong> — the location will be updated.</p><p>Also, this setting only applies to the <strong>current Windows user account</strong>. If the classroom computer has multiple accounts, each account needs to enable it individually.</p></div><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="run-directly" tabindex="-1">Run Directly <a class="header-anchor" href="#run-directly" aria-label="Permalink to &quot;Run Directly&quot;">​</a></h3><p>Press <kbd>Win</kbd> + <kbd>R</kbd>, enter the command and press Enter:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://fold</span></span></code></pre></div><p>You can also enter it in the browser address bar — it will prompt you to confirm opening ICC-CE.</p><h3 id="create-a-desktop-shortcut" tabindex="-1">Create a Desktop Shortcut <a class="header-anchor" href="#create-a-desktop-shortcut" aria-label="Permalink to &quot;Create a Desktop Shortcut&quot;">​</a></h3><ol><li>Right-click on the desktop → New → Shortcut</li><li>Enter the command as the location, e.g., <code>icc://clear</code></li><li>Give it a name, e.g., &quot;Clear Ink&quot;</li></ol><p>Double-click to use it. You can also right-click the shortcut → Properties → Shortcut key to assign a keyboard shortcut.</p><h3 id="create-a-batch-script" tabindex="-1">Create a Batch Script <a class="header-anchor" href="#create-a-batch-script" aria-label="Permalink to &quot;Create a Batch Script&quot;">​</a></h3><p>Create a new <code>.bat</code> file with multiple commands:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> icc://config-profile/switch?name=上课</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /t </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> icc://unfold</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Leave some time between consecutive commands</p><p>Each command will launch the software. If you send them too quickly, some may not be processed. Using <code>timeout /t 1</code> as shown above to add a one-second delay is safer.</p></div><h3 id="for-classroom-control-systems" tabindex="-1">For Classroom Control Systems <a class="header-anchor" href="#for-classroom-control-systems" aria-label="Permalink to &quot;For Classroom Control Systems&quot;">​</a></h3><p>Most classroom control systems support &quot;Execute Custom Command&quot; or &quot;Open Link&quot;. Enter the <code>icc://</code> command there. If the software isn&#39;t running, it will start automatically; if it&#39;s already running, the command will execute directly.</p><h2 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h2><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://fold</code></td><td>Collapse the toolbar</td></tr><tr><td><code>icc://unfold</code></td><td>Expand the toolbar</td></tr><tr><td><code>icc://toggle</code></td><td>Toggle between collapsed and expanded</td></tr><tr><td><code>icc://thoroughhideon</code></td><td>Enable &quot;Thoroughly hide when collapsed&quot;</td></tr><tr><td><code>icc://thoroughhideoff</code></td><td>Disable &quot;Thoroughly hide when collapsed&quot;</td></tr><tr><td><code>icc://thoroughhidetoggle</code></td><td>Toggle this option</td></tr></tbody></table><p>The <code>thoroughhide</code> commands will <strong>modify and save the setting</strong>, just like changing it manually in Settings.</p><h3 id="pen-tools" tabindex="-1">Pen &amp; Tools <a class="header-anchor" href="#pen-tools" aria-label="Permalink to &quot;Pen &amp; Tools&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://tool/pen</code></td><td>Switch to pen</td></tr><tr><td><code>icc://tool/cursor</code></td><td>Switch to cursor (mouse mode)</td></tr><tr><td><code>icc://tool/eraser</code></td><td>Switch to area eraser</td></tr><tr><td><code>icc://tool/eraserbystrokes</code></td><td>Switch to stroke eraser</td></tr><tr><td><code>icc://tool/select</code></td><td>Switch to lasso selection</td></tr></tbody></table><h3 id="ink" tabindex="-1">Ink <a class="header-anchor" href="#ink" aria-label="Permalink to &quot;Ink&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://clear</code></td><td>Clear current ink</td></tr><tr><td><code>icc://clearall</code></td><td>Clear ink and cannot be undone</td></tr><tr><td><code>icc://undo</code></td><td>Undo</td></tr><tr><td><code>icc://redo</code></td><td>Redo</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Content cleared with clearall cannot be recovered</p><p>Ink cleared with <code>icc://clear</code> can still be restored with <code>icc://undo</code>. <code>icc://clearall</code> clears the undo history as well — <strong>cannot be restored</strong>. Be careful not to confuse them when creating shortcuts.</p></div><h3 id="whiteboard-pages" tabindex="-1">Whiteboard Pages <a class="header-anchor" href="#whiteboard-pages" aria-label="Permalink to &quot;Whiteboard Pages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://nextpage</code></td><td>Next page</td></tr><tr><td><code>icc://previouspage</code></td><td>Previous page</td></tr><tr><td><code>icc://newpage</code></td><td>New page</td></tr><tr><td><code>icc://deletepage</code></td><td>Delete current page</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://whiteboard</code></td><td>Open/close whiteboard</td></tr><tr><td><code>icc://rand</code></td><td>Random name picker</td></tr><tr><td><code>icc://randone</code></td><td>Pick one person</td></tr><tr><td><code>icc://timer</code></td><td>Countdown timer</td></tr><tr><td><code>icc://screenshot</code></td><td>Take screenshot and insert onto canvas</td></tr></tbody></table><h3 id="configuration-profiles" tabindex="-1">Configuration Profiles <a class="header-anchor" href="#configuration-profiles" aria-label="Permalink to &quot;Configuration Profiles&quot;">​</a></h3><p>If you have created multiple configuration profiles (e.g., &quot;Chinese Class&quot;, &quot;Math Class&quot;), you can switch between them directly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://config-profile/switch?name=ProfileName</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">The profile name must match exactly</p><p>Case, spaces, and characters must match your profile name exactly. If wrong, there will be no prompt — it simply won&#39;t work. Spaces and Chinese characters in the name are generally fine, just write them directly.</p></div><h3 id="open-settings" tabindex="-1">Open Settings <a class="header-anchor" href="#open-settings" aria-label="Permalink to &quot;Open Settings&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://settings</span></span></code></pre></div><p>You can also jump directly to a specific settings page, for example, to open Canvas settings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://settings/CanvasPage</span></span></code></pre></div><h3 id="restart-exit" tabindex="-1">Restart &amp; Exit <a class="header-anchor" href="#restart-exit" aria-label="Permalink to &quot;Restart &amp; Exit&quot;">​</a></h3><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://restart</code></td><td>Restart the software</td></tr><tr><td><code>icc://exit</code></td><td>Exit the software</td></tr><tr><td><code>icc://restart/admin</code></td><td>Restart as administrator</td></tr><tr><td><code>icc://restart/normal</code></td><td>Restart as normal user</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">These commands are throttled to once per 3 seconds</p><p>This prevents control panel buttons from being double-pressed and causing repeated restarts. Duplicate commands within 3 seconds will be ignored — this is normal behavior.</p></div><h2 id="ink-freeze" tabindex="-1">Ink Freeze <a class="header-anchor" href="#ink-freeze" aria-label="Permalink to &quot;Ink Freeze&quot;">​</a></h2><p>For use with the ink freeze feature:</p><table tabindex="0"><thead><tr><th>URL</th><th>Effect</th></tr></thead><tbody><tr><td><code>icc://freeze</code></td><td>Freeze current page</td></tr><tr><td><code>icc://unfreeze</code></td><td>Unfreeze current page</td></tr><tr><td><code>icc://freeze/start</code></td><td>Start lesson</td></tr><tr><td><code>icc://freeze/end</code></td><td>End lesson</td></tr><tr><td><code>icc://freeze/cancel</code></td><td>Cancel</td></tr></tbody></table><p>To target a specific page, add <code>?page=</code> (range 0 to 100):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://freeze?page=3</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Using URL to unfreeze bypasses the password</p><p>If you have set a password for frozen pages, <code>icc://unfreeze</code> <strong>will not prompt for the password</strong> — it will unfreeze directly.</p><p>This is also why &quot;External Protocol Call&quot; is disabled by default. If you rely on the freeze password to prevent students from modifying content, do not enable this toggle, or at least don&#39;t create unfreeze shortcuts on the desktop.</p></div><h2 id="command-not-working" tabindex="-1">Command Not Working? <a class="header-anchor" href="#command-not-working" aria-label="Permalink to &quot;Command Not Working?&quot;">​</a></h2><p>Check in order:</p><ol><li><strong>Is the toggle enabled?</strong> — Settings → Startup → External Protocol Call (icc://). This is the most common cause</li><li><strong>Has the software folder been moved?</strong> — After moving, the toggle needs to be turned off and on again</li><li><strong>Is the URL spelled correctly?</strong> — Commands are case-insensitive, <code>icc://Fold</code> and <code>icc://fold</code> both work, but typos will not be recognized</li><li><strong>Does the configuration profile name match?</strong> — Profile names are case-sensitive and must match exactly</li><li><strong>Is it a repeated restart/exit command within 3 seconds?</strong> — This is an intentional limitation</li></ol><p>If everything checks out and it still doesn&#39;t work, check the latest log file in the software&#39;s <code>Logs</code> folder. Search for <code>URI</code> to see what command the software received and why it didn&#39;t execute. Attaching this log when reporting issues will speed things up significantly.</p><h2 id="related-content" tabindex="-1">Related Content <a class="header-anchor" href="#related-content" aria-label="Permalink to &quot;Related Content&quot;">​</a></h2><ul><li><a href="/website/en/guide/files-and-data">Configuration &amp; Data Directories</a> — Where configuration profiles are stored</li><li><a href="/website/en/guide/settings">Settings Guide</a> — Explanation of all settings</li><li><a href="/website/en/dev/core/uri">URI Protocol</a> — Complete command reference and implementation details for developers</li></ul>`,58))])}const w=a(l,[["render",h]]);export{k as __pageData,w as default};
